// Generator for whitespace/strip probe corpora. Writes JSON files under /workspace/corpus/.
import { writeFileSync } from 'node:fs';

export const CHARS = [
  ['SP', ' '],
  ['TAB', '\t'],
  ['LF', '\n'],
  ['CR', '\r'],
  ['CRLF', '\r\n'],
  ['FF', '\f'],           // \x0c
  ['VT', '\v'],           // \x0b
  ['NBSP', ' '],
  ['ENQUAD', ' '],
  ['IDEOSP', '　'],
  ['ZWSP', '​'],
  ['LS', ' '],
  ['PS', ' '],
  ['NEL', ''],
  ['FS', ''],
  ['GS', ''],
  ['RS', ''],
  ['US', ''],
  ['OGHAM', ' '],
  ['MONGVOWSEP', '᠎'],
  ['NNBSP', ' '],
  ['MMSP', ' '],
  ['BOM', '﻿'],
  ['FIGSP', ' '],
  ['HAIRSP', ' '],
  ['THINSP', ' '],
  ['PUNCTSP', ' '],
  ['ZWNJ', '‌'],
  ['WJ', '⁠'],
  ['SOH', ''],
  ['BEL', ''],
  ['BS', ' '],
  ['ESC', ''],
  ['DEL', ''],
  ['C1_80', ''],
  ['C1_9F', ''],
  ['SHY', '­'],
];

const args = process.argv.slice(2);
const mode = args[0];
const out = args[1];

const build = {
  // absorption discriminator: ";X-- c\nSELECT 2"
  absorb: () => CHARS.map(([, c]) => ';' + c + '-- c\nSELECT 2'),
  // strip discriminator: "X" + "A" + "X"
  strip: () => CHARS.map(([, c]) => c + 'A' + c),
  // leading only
  striplead: () => CHARS.map(([, c]) => c + 'A'),
  // trailing only
  striptrail: () => CHARS.map(([, c]) => 'A' + c),
  // char alone
  alone: () => CHARS.map(([, c]) => c),
  // char alone with semicolon prefix
  semi: () => CHARS.map(([, c]) => ';' + c),
  // does X split a token (whitespace/newline separate tokens)?  "SELECT 1 X 2"
  sep: () => CHARS.map(([, c]) => 'AA' + c + 'BB'),
};

if (!build[mode]) {
  console.error('modes: ' + Object.keys(build).join(', '));
  process.exit(64);
}
const entries = build[mode]();
writeFileSync(out, JSON.stringify(entries, null, 0));
console.error(`wrote ${entries.length} entries to ${out}`);
for (let i = 0; i < CHARS.length; i++) console.error(`${i}\t${CHARS[i][0]}`);

// Generator for whitespace/strip probe corpora. Writes JSON files under /workspace/corpus/.
import { writeFileSync } from 'node:fs';

const cp = (n) => String.fromCodePoint(n);

export const CHARS = [
  ['SP U+0020', cp(0x20)],
  ['TAB U+0009', cp(0x09)],
  ['LF U+000A', cp(0x0a)],
  ['CR U+000D', cp(0x0d)],
  ['CRLF', cp(0x0d) + cp(0x0a)],
  ['LFCR', cp(0x0a) + cp(0x0d)],
  ['FF U+000C', cp(0x0c)],
  ['VT U+000B', cp(0x0b)],
  ['NBSP U+00A0', cp(0xa0)],
  ['ENQUAD U+2000', cp(0x2000)],
  ['IDEOSP U+3000', cp(0x3000)],
  ['ZWSP U+200B', cp(0x200b)],
  ['LS U+2028', cp(0x2028)],
  ['PS U+2029', cp(0x2029)],
  ['NEL U+0085', cp(0x85)],
  ['FS U+001C', cp(0x1c)],
  ['GS U+001D', cp(0x1d)],
  ['RS U+001E', cp(0x1e)],
  ['US U+001F', cp(0x1f)],
  ['OGHAM U+1680', cp(0x1680)],
  ['MONGVOWSEP U+180E', cp(0x180e)],
  ['NNBSP U+202F', cp(0x202f)],
  ['MMSP U+205F', cp(0x205f)],
  ['BOM U+FEFF', cp(0xfeff)],
  ['FIGSP U+2007', cp(0x2007)],
  ['HAIRSP U+200A', cp(0x200a)],
  ['THINSP U+2009', cp(0x2009)],
  ['PUNCTSP U+2008', cp(0x2008)],
  ['ZWNJ U+200C', cp(0x200c)],
  ['WJ U+2060', cp(0x2060)],
  ['SOH U+0001', cp(0x01)],
  ['BEL U+0007', cp(0x07)],
  ['BS U+0008', cp(0x08)],
  ['ESC U+001B', cp(0x1b)],
  ['DEL U+007F', cp(0x7f)],
  ['C1_80 U+0080', cp(0x80)],
  ['C1_9F U+009F', cp(0x9f)],
  ['SHY U+00AD', cp(0xad)],
];

const args = process.argv.slice(2);
const mode = args[0];
const out = args[1];

const build = {
  absorb: () => CHARS.map(([, c]) => ';' + c + '-- c\nSELECT 2'),
  strip: () => CHARS.map(([, c]) => c + 'A' + c),
  striplead: () => CHARS.map(([, c]) => c + 'A'),
  striptrail: () => CHARS.map(([, c]) => 'A' + c),
  alone: () => CHARS.map(([, c]) => c),
  semi: () => CHARS.map(([, c]) => ';' + c),
  sep: () => CHARS.map(([, c]) => 'AA' + c + 'BB'),
  // whitespace-only trailing statement suppression: "A;" + X  (X alone as final chunk)
  tailonly: () => CHARS.map(([, c]) => 'A;' + c),
  // does X after ; behave as newline: ";X;"
  semixsemi: () => CHARS.map(([, c]) => ';' + c + ';'),
