// Broad scan: for every candidate code point X, probe ";X" and ";X-- c\nZ".
// (This is a PROBE script, not deliverable code, so regex/Unicode property escapes are fine.)
import { writeFileSync } from 'node:fs';

const cands = [];
for (let n = 1; n <= 0x2ffff; n++) {
  if (n >= 0xd800 && n <= 0xdfff) continue;
  const ch = String.fromCodePoint(n);
  let keep = false;
  if (n <= 0xff) keep = true;
  else if (/\s/u.test(ch)) keep = true;
  else if (/\p{Zs}|\p{Zl}|\p{Zp}|\p{Cf}|\p{Cc}/u.test(ch)) keep = true;
  else if (/\p{White_Space}/u.test(ch)) keep = true;
  if (keep) cands.push(n);
}
writeFileSync('/tmp/cands.json', JSON.stringify(cands));
const mode = process.argv[2] || 'semi';
const build = mode === 'semi'
  ? (ch) => ';' + ch
  : (ch) => ';' + ch + '-- c\nZ';
writeFileSync(process.argv[3], JSON.stringify(cands.map((n) => build(String.fromCodePoint(n)))));
console.error('candidates: ' + cands.length);

// Run a corpus against the executable and print compact "index<TAB>codepoint<TAB>output" lines.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test2_executable';
const entries = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const labels = process.argv[3] ? JSON.parse(readFileSync(process.argv[3], 'utf8')) : null;
const groups = new Map();
for (let i = 0; i < entries.length; i++) {
  const r = spawnSync(EXE, ['--a', String(entries[i])], { encoding: 'utf8' });
  const key = (r.stdout ?? '').trim();
  const lab = labels ? 'U+' + labels[i].toString(16).toUpperCase().padStart(4, '0') : String(i);
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(lab);
}
for (const [k, v] of groups) console.log(JSON.stringify(k) + '  ::  n=' + v.length + '  ' + v.join(' '));

